"use client";
import { useState } from "react"; import { prepareDocumentUpload,finalizeDocumentUpload } from "@/app/actions/documents"; import { uploadDocument } from "@/lib/uploads/documents"; import { Button } from "@/components/ui/button";
export function DocumentForm(){const [message,setMessage]=useState("");return <form className="space-y-3 rounded-lg border bg-white p-4" onSubmit={async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);const file=f.get("file");try{if(!(file instanceof File)||!file.size)throw new Error("Choose a file");const mime=file.type;const prepared=await prepareDocumentUpload({documentType:String(f.get("documentType")),filename:file.name,mimeType:mime});await uploadDocument(file,prepared.objectPath);await finalizeDocumentUpload({documentType:String(f.get("documentType")),driverId:String(f.get("driverId")||"")||undefined,unitId:String(f.get("unitId")||"")||undefined,expiresOn:f.get("expiresOn"),mimeType:mime,sizeBytes:file.size,sha256:"0".repeat(64),objectPath:prepared.objectPath});setMessage("Document saved.");}catch(err){setMessage(err instanceof Error?err.message:"Could not save document");}}}><h2 className="font-semibold">Upload document</h2><select name="documentType" className="min-h-11 w-full rounded border p-3"><option value="or_cr">OR/CR</option><option value="driver_license">Driver license</option><option value="mtop_franchise">MTOP franchise</option><option value="insurance">Insurance</option></select><input name="expiresOn" required type="date" className="min-h-11 w-full rounded border p-3"/><input name="file" required type="file" accept="image/jpeg,image/png,image/webp,application/pdf" className="min-h-11 w-full rounded border p-3"/><Button type="submit">Upload document</Button>{message&&<p className="text-sm text-slate-600">{message}</p>}</form>}
